// The explainer site: the page itself comes from public/ (static assets); this worker serves what lives in the R2
// bucket. tools/publish.py writes the bucket: v/<id>/<hash>.mp4 videos, t/<id>/<hash>.jpg thumbnails and
// index.json, the list the page reads. Video and thumbnail names carry the file's hash, so they never change once
// written and can be cached forever; only index.json is ever overwritten.

const IMMUTABLE = "public, max-age=31536000, immutable";

export default {
	async fetch(req, env) {
		const url = new URL(req.url);
		const path = decodeURIComponent(url.pathname);
		if (req.method !== "GET" && req.method !== "HEAD") return new Response("method not allowed", { status: 405 });
		if (path === "/index.json") return object(req, env, "index.json", "no-cache");
		if (path === "/feed.xml") return feed(env, url.origin);
		if (path.startsWith("/v/") || path.startsWith("/t/")) return object(req, env, path.slice(1), IMMUTABLE);
		return env.ASSETS.fetch(req);
	},
};

// One object from the bucket, with Range (a video player seeking) and conditional requests (a cached copy) handled.
async function object(req, env, key, cache) {
	if (key.includes("..")) return new Response("not found", { status: 404 });
	const range = req.headers.has("range");
	const obj = req.method === "HEAD"
		? await env.VIDEOS.head(key)
		: await env.VIDEOS.get(key, { range: req.headers, onlyIf: req.headers });
	if (!obj) return new Response("not found", { status: 404 });
	const h = new Headers();
	obj.writeHttpMetadata(h);
	h.set("etag", obj.httpEtag);
	h.set("cache-control", cache);
	h.set("accept-ranges", "bytes");
	if (!("body" in obj)) {   // a HEAD, or an If-None-Match that matched
		if (req.method === "HEAD") { h.set("content-length", obj.size); return new Response(null, { headers: h }); }
		return new Response(null, { status: 304, headers: h });
	}
	if (range && obj.range) {
		const { offset = 0, length = obj.size - offset } = obj.range;
		h.set("content-range", `bytes ${offset}-${offset + length - 1}/${obj.size}`);
		h.set("content-length", length);
		return new Response(obj.body, { status: 206, headers: h });
	}
	h.set("content-length", obj.size);
	return new Response(obj.body, { headers: h });
}

// RSS, newest change first: a new video is "New: <title>", a replaced one "Updated: <title>".
async function feed(env, origin) {
	const obj = await env.VIDEOS.get("index.json");
	const idx = obj ? await obj.json() : { videos: [] };
	const esc = (s) => String(s).replace(/[<>&"']/g, (c) => ({ "<": "&lt;", ">": "&gt;", "&": "&amp;", '"': "&quot;", "'": "&apos;" })[c]);
	const items = [...idx.videos].sort((a, b) => b.updated - a.updated).slice(0, 50).map((v) => {
		const isNew = v.updated <= v.added;
		return `<item><title>${esc((isNew ? "New: " : "Updated: ") + v.title)}</title>`
			+ `<link>${origin}/#/${esc(v.id)}</link><guid isPermaLink="false">${esc(v.id + "@" + v.v)}</guid>`
			+ `<pubDate>${new Date(v.updated * 1000).toUTCString()}</pubDate>`
			+ `<enclosure url="${origin}/${esc(v.thumb)}" type="image/jpeg" length="0"/></item>`;
	}).join("\n");
	const xml = `<?xml version="1.0" encoding="UTF-8"?>\n<rss version="2.0"><channel><title>Explainers</title>`
		+ `<link>${origin}/</link><description>Narrated explainer videos, as they are made and updated</description>\n${items}\n</channel></rss>`;
	return new Response(xml, { headers: { "content-type": "application/rss+xml; charset=utf-8", "cache-control": "no-cache" } });
}
